#define MAXSIZE 20
typedef struct {
    int data[MAXSIZE];
    int length;
} SeqList;

int Insert(SeqList *L, int i, int x)
{
    int j;
    if (i < 1 || i > L->length + 1)
        return 0;
    if (L->length >= MAXSIZE)
        return 0;
    for (j = L->length - 1; j >= i - 1; j--)
        L->data[j + 1] = L->data[j];
    L->data[i - 1] = x;
    L->length++;
    return 1;
}

int main(void)
